import{c as t,Q as a,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Circuit Tracing: Revealing Computational Graphs in Language Models","description":"","frontmatter":{"url":"https://transformer-circuits.pub/2025/attribution-graphs/methods.html","title":"Circuit Tracing: Revealing Computational Graphs in Language Models","archived_date":"2026-06-09T00:00:00.000Z","authors":["Emmanuel Ameisen","Jack Lindsey","Adam Pearce","Wes Gurnee","Nicholas L. Turner","Brian Chen","Craig Citro","David Abrahams","Shan Carter","Basil Hosmer","Jonathan Marcus","Michael Sklar","Adly Templeton","Trenton Bricken","Callum McDougall","Hoagy Cunningham","Thomas Henighan","Adam Jermyn","Andy Jones","Andrew Persic","Zhenyi Qi","T. Ben Thompson","Sam Zimmerman","Kelley Rivoire","Thomas Conerly","Chris Olah","Joshua Batson"],"published_date":"2025-03-27T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-03-27-circuit-tracing-attribution-graphs-language-models.md","filePath":"research/papers/2025-03-27-circuit-tracing-attribution-graphs-language-models.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-03-27-circuit-tracing-attribution-graphs-language-models.md"};function n(s,e,l,c,u,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="circuit-tracing-revealing-computational-graphs-in-language-models" tabindex="-1">Circuit Tracing: Revealing Computational Graphs in Language Models <a class="header-anchor" href="#circuit-tracing-revealing-computational-graphs-in-language-models" aria-label="Permalink to &quot;Circuit Tracing: Revealing Computational Graphs in Language Models&quot;">​</a></h1><p><strong>Authors:</strong> Emmanuel Ameisen, Jack Lindsey, Adam Pearce, Wes Gurnee, Nicholas L. Turner, Brian Chen, Craig Citro, David Abrahams, Shan Carter, Basil Hosmer, Jonathan Marcus, Michael Sklar, Adly Templeton, Trenton Bricken, Callum McDougall, Hoagy Cunningham, Thomas Henighan, Adam Jermyn, Andy Jones, Andrew Persic, Zhenyi Qi, T. Ben Thompson, Sam Zimmerman, Kelley Rivoire, Thomas Conerly, Chris Olah, Joshua Batson</p><p><strong>Year:</strong> 2025</p><p><strong>Published:</strong> March 27, 2025</p><p><strong>Venue/Publisher:</strong> Transformer Circuits Thread (Anthropic)</p><p><strong>ArXiv:</strong> N/A (published at transformer-circuits.pub)</p><p><strong>URL:</strong> <a href="https://transformer-circuits.pub/2025/attribution-graphs/methods.html" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2025/attribution-graphs/methods.html</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>This paper introduces a methodology for uncovering the computational mechanisms underlying language model behaviors by constructing attribution graphs — directed computational graphs that trace information flow from input tokens to output predictions on specific prompts. The key innovation is replacing MLP components with interpretable cross-layer transcoders (CLTs) that extract sparsely-active features spanning multiple layers. Combined with frozen attention patterns and error adjustments, this produces a local replacement model that faithfully approximates the underlying model while being fully interpretable. Case studies on factual recall, addition, and acronym generation demonstrate step-by-step descriptions of model computation, with application to Claude 3.5 Haiku.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Cross-layer transcoders (CLTs):</strong> novel architecture that extracts sparsely-active features spanning multiple model layers simultaneously, overcoming a key limitation of per-layer SAEs where features computed over multiple residual stream transformations are artificially split across layer boundaries</li><li><strong>Attribution graph framework:</strong> systematic methodology for tracing information flow through features from inputs to outputs for any specific prompt, producing a human-readable directed graph of computational steps</li><li><strong>Local replacement model:</strong> approach combining CLT features with frozen attention patterns and error adjustment nodes to faithfully approximate underlying model behavior on specific prompts — enabling mechanistic analysis that is simultaneously accurate and interpretable</li><li><strong>Interactive open-source visualization tools</strong> for navigating complex computational graphs and testing hypotheses by modifying individual feature values, making circuit analysis accessible without deep ML infrastructure</li><li><strong>Comprehensive perturbation-based validation</strong> demonstrating mechanistic faithfulness of identified circuits: circuits are validated by patching in modified feature values and measuring whether model outputs change as predicted by the circuit structure</li><li><strong>Application at scale to Claude 3.5 Haiku</strong>, providing the most detailed circuit-level account of a frontier model to date — covering factual recall, arithmetic, and linguistic pattern tasks with mechanistic precision</li><li><strong>Global circuit analysis methods</strong> for understanding how feature interactions generalize across multiple prompts, including techniques for handling &quot;interference&quot; in virtual weights when aggregating attributions</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The central methodological innovation is the <strong>cross-layer transcoder (CLT)</strong>. Prior work (SAEs trained per layer) approximated MLP computations layer by layer, requiring features computed over multiple residual stream updates to be re-identified at each new layer — an artificial decomposition that obscured computational continuity. CLTs instead learn to predict the total effect of a contiguous sequence of MLP layers on the residual stream in a single forward pass, extracting a dictionary of features that are active sparsely across the full span. This allows features that participate in multi-layer computations (such as multi-step reasoning or compositional operations) to be identified as single coherent units rather than fragmented across layer-specific SAEs.</p><p>The <strong>local replacement model</strong> is constructed by swapping the trained model&#39;s MLP components with the CLTs and freezing the attention patterns as computed by the original model. The attention patterns are not replaced but left as-is: attention weights capture which tokens attend to which other tokens, and these patterns are kept intact because the focus of the methodology is on the MLP-driven feature computations. Error adjustment nodes are added to account for the residual approximation error of the CLTs, ensuring that the total residual stream value at each layer accurately matches the original model&#39;s activations. The result is a model that computes identical outputs to the original but whose computation is expressed entirely in terms of interpretable CLT features and attention patterns.</p><p><strong>Attribution graphs</strong> are constructed from the local replacement model using gradient-based attribution: for each feature active on a given prompt, the contribution of every upstream feature to that feature&#39;s activation is computed via a linearized gradient pass. These pairwise attributions are aggregated into a directed graph where nodes are features (and attention patterns) and edges are weighted by attribution strength. The graph is then pruned by removing low-weight edges, leaving a sparse but mechanistically faithful subgraph that constitutes the circuit for the given behavior. This graph can be interactively explored: hovering over nodes reveals what the feature represents (via maximum activating examples), and modifying edge weights or node activations reveals how the circuit&#39;s output changes.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li><strong>Factual recall circuits</strong> for statements like &quot;The capital of France is Paris&quot; were traced end-to-end: input token features encoding the country name activate stored &quot;capital city&quot; association features that in turn activate the output token for the correct city, with the full computational path spanning multiple layers and identifiable at each step</li><li><strong>Addition circuits</strong> for simple arithmetic (e.g., 3 + 5 = 8) were recovered, showing that the model represents intermediate summand values as features and uses MLP computations to combine them, with clear separation between the &quot;operand representation&quot; phase and the &quot;summation&quot; phase</li><li><strong>Acronym generation</strong> (producing &quot;NATO&quot; from &quot;North Atlantic Treaty Organization&quot;) was analyzed, revealing features that encode the first-letter positions of constituent words and features that compose them into the output acronym</li><li><strong>Validation via patching:</strong> in all three case studies, manually setting features to values inconsistent with the proposed circuit mechanism (e.g., swapping a &quot;France&quot; feature for a &quot;Germany&quot; feature) produced exactly the output shifts predicted by the circuit structure, confirming mechanistic faithfulness</li><li>The CLT architecture achieves <strong>lower reconstruction error</strong> than equivalent per-layer SAEs while using the same or fewer total features, demonstrating that cross-layer span is a genuine architectural improvement</li><li>Application to <strong>Claude 3.5 Haiku</strong> produced attribution graphs that are qualitatively similar in structure to those found in smaller models, suggesting that the circuit-tracing methodology generalizes across model scales</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>The <strong>local replacement model</strong> is prompt-specific: a new attribution graph must be constructed for each prompt, making large-scale circuit analysis computationally expensive and preventing easy generalization to &quot;the circuit for task X&quot; across diverse inputs</li><li><strong>Attention patterns are frozen</strong> and not decomposed into interpretable components; the methodology treats attention as a black box, leaving the mechanism by which attention weights are computed unanalyzed</li><li><strong>Error adjustment nodes</strong> absorb residual approximation error and appear in attribution graphs as unexplained edges, potentially masking important computational steps that the CLTs have not captured</li><li>The methodology has been applied to only a <strong>subset of task types</strong> (factual recall, arithmetic, pattern completion); whether the approach generalizes cleanly to complex multi-step reasoning, open-ended generation, or adversarial robustness is not demonstrated</li><li><strong>Causal completeness</strong> is validated by perturbation experiments but not formally proven; the circuits identified may be sufficient for the studied prompts without being necessary (there may be redundant pathways not captured)</li><li>The <strong>global circuit aggregation</strong> across multiple prompts remains methodologically early-stage; interference in virtual weights makes cross-prompt generalization difficult and the aggregated circuits may not cleanly represent general-purpose circuits in the model</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>This paper represents the state of the art in <strong>mechanistic interpretability at the circuit level</strong> for frontier models. While prior work (Towards Monosemanticity, Scaling Monosemanticity) established that individual features inside models are interpretable, this work goes further by asking how those features interact to produce specific behaviors. The attribution graph framework provides a principled answer: for any given input and output, one can construct a computational graph that shows exactly which features were activated, how they influenced each other, and which ones were causally responsible for the output.</p><p>For <strong>AI safety</strong>, the implications are substantial. If the circuits underlying behaviors like &quot;refusing dangerous requests,&quot; &quot;producing honest responses,&quot; or &quot;following instructions&quot; can be identified at the feature level, then safety audits can move beyond behavioral testing to mechanistic verification. A model that has been steered to refuse harmful requests via RLHF may have done so through superficial output-level changes, or through genuine internalization of safety-relevant reasoning circuits — and circuit tracing provides, for the first time, a methodology for distinguishing these cases.</p><p>For <strong>AI engineers</strong>, the open-source interactive visualization tools lower the barrier for applying circuit analysis to custom models. The CLT architecture can be trained on any transformer with accessible activations, and the attribution graph methodology requires only gradient access — meaning that practitioners can begin applying this approach to their own models without reproducing the full Anthropic research pipeline.</p>',29)])])}const g=t(o,[["render",n]]);export{d as __pageData,g as default};
